function fsVal(field) {
  if (!field) return null;
  if (field.stringValue  !== undefined) return field.stringValue;
  if (field.integerValue !== undefined) return Number(field.integerValue);
  if (field.doubleValue  !== undefined) return field.doubleValue;
  if (field.booleanValue !== undefined) return field.booleanValue;
  if (field.nullValue    !== undefined) return null;
  if (field.mapValue) {
    const out = {};
    for (const [k, v] of Object.entries(field.mapValue.fields || {})) out[k] = fsVal(v);
    return out;
  }
  if (field.arrayValue) return (field.arrayValue.values || []).map(fsVal);
  return null;
}

const doc = $json;
const payload = ($('Webhook').first().json.body) || {};

if (!doc || !doc.fields || !doc.name) {
  return [{ json: { found: false, reason: 'lead_not_found', leadId: payload.leadId || '' } }];
}

const nameParts = doc.name.split('/');
const leadId = nameParts[nameParts.length - 1];
const lead = { id: leadId };
for (const [k, v] of Object.entries(doc.fields)) lead[k] = fsVal(v);

// email_links[] is append-only (every writer in this project only ever
// appends -- same assumption workflow 33's "Build lead patch" and workflow
// 11 rely on), so the LAST entry with a non-empty graphMessageId is the
// newest real message we can reply into. Walk backward so a later chip
// that's missing graphMessageId (e.g. a manually resolve-thread-only link)
// doesn't block an earlier one that has it.
const links = Array.isArray(lead.email_links) ? lead.email_links : [];
let target = null;
for (let i = links.length - 1; i >= 0; i--) {
  if (links[i] && links[i].graphMessageId) { target = links[i]; break; }
}

return [{ json: {
  found: !!target,
  reason: target ? '' : 'no_graph_message_id',
  graphMessageId: target ? target.graphMessageId : '',
  lead,
  leadId,
  payloadSubject: payload.subject || '',
  payloadBody: payload.body || '',
  label: payload.label || '',
  followupNum: (payload.followupNum !== undefined && payload.followupNum !== null) ? payload.followupNum : null
} }];

const draft = $json; // response from "Create reply draft"
const picked = $('Pick reply target').item.json;

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Graph HTML bodies don't auto-render raw newlines the way mailto: (and the
// app's own plain-text follow-up drafts) do -- a bare "\n\n" just sits there
// as literal whitespace once contentType is 'HTML' instead of becoming a
// paragraph break. Split on blank-line paragraph breaks, escape each
// paragraph, then turn any remaining single '\n' inside a paragraph into
// <br> -- matches how the app's plain-text drafts already use '\n' for a
// soft line break within a paragraph and '\n\n' between paragraphs.
function textToHtml(text) {
  const paragraphs = String(text || '').split(/\n\n+/).filter(p => p.trim() !== '');
  const parasHtml = paragraphs
    .map(p => '<div>' + esc(p).replace(/\n/g, '<br>') + '</div>')
    .join('<div>&nbsp;</div>');
  return parasHtml;
}

// FIX (2026-08-20, found on the first live test): Graph's createReply
// addresses the draft back to the SENDER of the message being replied to,
// not to the other party -- when that message is one Justin sent himself
// (which is what email_links[].graphMessageId always points at: the last
// outbound message, qualifying email or a prior follow-up), the draft's
// toRecipients comes back as Justin's own address. Confirmed live: a real
// test send landed in Justin's own inbox instead of the lead's. So this
// can't rely on Graph's default recipient at all -- the PATCH step below
// now explicitly overwrites toRecipients with the lead's real email,
// every time, regardless of what createReply defaulted to.
const toEmail = (picked.lead && picked.lead.email) || '';

// FIX (2026-08-20, found on the second live test): no signature. Same gap
// workflow 33 already hit and solved -- this is an automated Graph send,
// not something going out through Justin's actual Outlook client, so there
// is no client-side signature to fall back on the way there is for the
// app's manual mailto: follow-ups (see project memory
// no-signature-block-in-drafts.md -- that note is specifically about the
// mailto: path, where Outlook auto-signs; it does not apply here). Reusing
// the exact same signature block workflow 33's "Render qualifying email"
// node already uses, verbatim, so every automated send looks consistent.
const signatureHtml = [
  '<div>&nbsp;</div>',
  '<div style="color:#1155CC;font-weight:bold;">Justin Cho | Business Development Executive</div>',
  '<div>218 Machlin Ct. | Walnut | California | 91789 | United States of America</div>',
  '<div style="font-size:9pt;">Cell: +1 (657) -620-7016</div>',
  '<div style="margin-top:6px;"><img src="https://www.cubework.com/logo/cubework-logo.svg" alt="Cubework" style="height:26px;display:block;"></div>',
  '<div style="font-size:9pt;font-style:italic;margin-top:6px;">NOTICE: This message, and any attachments, contain(s) information that may be confidential or protected by privilege from disclosure and is intended only for the individual or entity named above. No one else may disclose copy, distribute, or use the contents of this message for any purpose. Its unauthorized use, dissemination, or duplication is strictly prohibited and may be unlawful. If you receive this message in error or are not an authorized recipient, please immediately delete the message and any attachments and notify the sender.</div>'
].join('');

const bodyHtml = '<div style="font-family:Aptos,Calibri,Helvetica,sans-serif;font-size:12pt;color:rgb(0,0,0)">' + textToHtml(picked.payloadBody) + signatureHtml + '</div>';

return [{ json: {
  ...picked,
  draftId: draft.id,
  draftConversationId: draft.conversationId || '',
  draftWebLink: draft.webLink || '',
  bodyHtml,
  toEmail
} }];

const picked = $('Convert body to HTML').item.json;
const lead = picked.lead;

// Same webLink fixup workflows 33/11 already use -- see those files for the
// full "This message might have been moved or deleted" backstory.
function fixThreadUrl(u) {
  if (!u || typeof u !== 'string') return u;
  const m = /[?&]ItemID=([^&]+)/i.exec(u);
  if (!m) return u.replace(/^(https?:\/\/)outlook\.cloud\.microsoft\//i, '$1outlook.office365.com/');
  const itemId = m[1];
  const pathId = itemId.replace(/%2F/gi, '-').replace(/%2B/gi, '-');
  return 'https://outlook.office365.com/mail/deeplink/read/' + pathId + '?ItemID=' + itemId + '&exvsurl=1';
}

const now = new Date().toISOString();
const webLink = fixThreadUrl(picked.draftWebLink || '');
const followupNum = picked.followupNum;

// New email_links[] entry captures THIS reply's own graphMessageId --
// deliberately not the id we replied INTO -- so a later follow-up walks
// forward onto this message instead of always replying to the original
// qualifying email. Same shape workflows 33/11 already write, so the app's
// existing chip rendering and reply-refresh polling need no new UI work.
const newLink = {
  id: 'el' + Date.now(),
  label: picked.label ? ('Follow-up: ' + picked.label) : 'Follow-up',
  subject: picked.payloadSubject || '',
  contact: lead.contact || lead.email || '',
  url: webLink,
  conversationId: picked.draftConversationId || '',
  graphMessageId: picked.draftId || ''
};
const existingLinks = Array.isArray(lead.email_links) ? lead.email_links : [];

// Full subject+body goes in notes[] (2026-08-21, Justin's ask: 'I need to
// see the whole email content, not just the followup #') -- same shape
// logFollowupSent() already writes for the manual mailto: path
// ('Subject: ...\n\n' + body), so both send paths render identically in
// the app's own entry/note history UI, no new UI branch needed. Plain-text
// payloadBody on purpose, not the HTML-converted bodyHtml -- matches what a
// human actually typed/reviewed in Batch Approve, not the Graph-ready markup.
const newEntry = {
  id: 'e' + Date.now(),
  text: 'Sent follow-up' + (picked.label ? (' (' + picked.label + ')') : '') + ' as a real Outlook reply' + (followupNum != null ? (', #' + followupNum) : '') + '.',
  kind: 'email',
  type: 'wait',
  dir: 'out',
  done: false,
  notes: [{ id: 'n' + Date.now(), type: 'text', text: 'Subject: ' + (picked.payloadSubject || '') + '\n\n' + (picked.payloadBody || '') }],
  createdAt: now,
  ...(followupNum != null ? { followupNum } : {})
};
const existingEntries = Array.isArray(lead.entries) ? lead.entries : [];

// Same minimal JS -> Firestore REST encoder workflows 33/17 already use.
function toFs(v) {
  if (v === null || v === undefined) return { nullValue: null };
  if (typeof v === 'boolean') return { booleanValue: v };
  if (typeof v === 'number') return Number.isInteger(v) ? { integerValue: String(v) } : { doubleValue: v };
  if (Array.isArray(v)) return { arrayValue: { values: v.map(toFs) } };
  if (typeof v === 'object') {
    const fields = {};
    for (const [k, val] of Object.entries(v)) fields[k] = toFs(val);
    return { mapValue: { fields } };
  }
  return { stringValue: String(v) };
}

// last_followup_* glance fields (round 6 of the 2026-08-19 escalation work,
// see project memory followup-auto-escalation.md) -- this workflow is now
// the thing responsible for keeping them current, since it replaces the
// app's own logFollowupSent() for this send path.
const patchFields = {
  updatedAt: toFs(now),
  email_links: toFs([...existingLinks, newLink]),
  entries: toFs([...existingEntries, newEntry]),
  last_followup_label: toFs(picked.label || ''),
  last_followup_num: toFs(followupNum != null ? followupNum : null),
  last_followup_sent_at: toFs(now)
};

return [{ json: {
  leadId: picked.leadId,
  patchBody: { fields: patchFields },
  updateMask: Object.keys(patchFields).join('&updateMask.fieldPaths='),
  contact: lead.contact || lead.company || '',
  company: lead.company || '',
  label: picked.label || ''
} }];
